/**
 * Sample data for the rebuilt Tulvo UI (default props + fidelity fixtures).
 *
 * DATA RULE: every visible string and number in a rebuilt screen comes from props.
 * The live snapshots contain AI sample data with possibly-real brands and the account
 * e-mail: NONE of it is used here. People and brands come ONLY from the cleared list
 * in research/11-names-clearance.md section 6. Product labels (deal statuses, roles,
 * onboarding steps, template and page names generated by Tulvo) are copied verbatim
 * from research/13-product-truth-day1.md and the DOM snapshots.
 *
 * Two datasets:
 *  - `tulvoFixtures`: the ad's default data (cleared names, consistent counts).
 *  - `captureMatch`:  same COUNTS / layout as each live capture, with cleared names, so a
 *                     rebuilt screen can be compared side by side with its screenshot.
 *
 * When src/tulvo/data/facts.ts (data engineer) lands, map it onto these types here.
 */

// ---------------------------------------------------------------- product vocabulary (verbatim)

/** Deal status dropdown options, in the app's order (template-edit-properties capture). */
export const DEAL_STATUSES = [
  "Prospecting",
  "Pitch Sent",
  "Negotiation",
  "Contract Review",
  "Signed",
  "Live",
  "Closed",
] as const;
export type DealStatus = (typeof DEAL_STATUSES)[number];

/** Priority values (seen: Urgent, High; the board CSS also styles k-medium / k-low). */
export const DEAL_PRIORITIES = ["Urgent", "High", "Medium", "Low"] as const;
export type DealPriority = (typeof DEAL_PRIORITIES)[number];

/** Values seen in the captures only. Do not add options the live template has not shown. */
export type DealType = "Affiliate Partnership" | "Sponsored Post";
export type DealChannel = "TikTok" | "Instagram";

/** Invite dialog roles and their descriptions (day2/02 capture). Never "Administrator". */
export const INVITE_ROLES = [
  { role: "Contributor", description: "Full control of their own items, read-only on everyone else's" },
  { role: "Editor", description: "Can create and change content across the workspace, but not manage it" },
  { role: "Admin", description: "Can do everything except delete the workspace or transfer ownership" },
] as const;
export type InviteRole = (typeof INVITE_ROLES)[number]["role"];
export type MemberRole = "Owner" | InviteRole;

