// ---------------------------------------------------------------- types

export type Workspace = {
  name: string;
  /** Letter in the workspace avatar tile (the app shows the first letter of the name). */
  initial: string;
  /** Second line under the workspace name, e.g. "1 member". */
  memberCountLabel: string;
};

export type SidebarPage = {
  id: string;
  title: string;
  /** The app lets a page icon carry its own colour (Waitlist: rgb(13, 13, 13)). Omit = muted. */
  iconColor?: string;
};

export type IntegrationItem = {
  id: string;
  /** Plain-text vendor name (never a logo, see IntegrationLogoSlot). */
  name: string;
  /** Google is shown greyed out (opacity-60, not clickable) in the live sidebar. */
  disabled?: boolean;
};

export type SidebarData = {
  recents: SidebarPage[];
  publicPages: SidebarPage[];
  privatePages: SidebarPage[];
  integrations: IntegrationItem[];
};

export type Deal = {
  id: string;
  /** "Item" (title) property. */
  title: string;
  status: DealStatus;
  dealType: DealType;
  priority: DealPriority;
  channel: DealChannel;
  brandName: string;
  contactName: string;
  /** Deal Value (number property), in dollars. */
  dealValue: number;
  /** Due Date, ISO yyyy-mm-dd. */
  dueDate: string;
  owners: string[];
};

/** Board tabs of Brand Deal Pipeline. `count` = the number chip next to the template name in the tab
 *  toolbar (captured: Prospecting Deals 3, Pitch Sent Campaigns 6; the other two are illustrative). */
export type BoardTab = { id: string; name: string; template: string; count: number };

export type PropertyType = "text" | "dropdown" | "number" | "date" | "attachment" | "contributors";
export type TemplateProperty = { name: string; type: PropertyType; options?: readonly string[] };
export type TemplateBoardUse = { name: string; tabs: string[]; lastUpdated: string };

export type DataTemplate = {
  id: string;
  name: string;
  /** "Used in ..." chips, e.g. ["Page tab", "Tasks", "Widget"]. */
  usedIn: string[];
  propertyCount: number;
  apiKeys: number;
  webhooks: number;
  properties?: TemplateProperty[];
  boards?: TemplateBoardUse[];
};

export type StatusCounts = Record<DealStatus, number>;
export type TrendPoint = { label: string; value: number };

export type WidgetValues = {
  statusCounts: StatusCounts;
  /** Due Date (trend) widget points. */
  dueDateTrend: TrendPoint[];
  /** "about 2 hours ago", "less than a minute ago" ... */
  updatedLabel: string;
};

export type WaitlistSignup = { id: string; name: string; email: string; creates: WaitlistCreate };

export type Member = {
  id: string;
  name: string;
  initials: string;
  email: string;
  role: MemberRole;
  status: "Active" | "Pending";
  isYou?: boolean;
};

export type TulvoDataset = {
  workspace: Workspace;
  sidebar: SidebarData;
  boardTabs: BoardTab[];
  deals: Deal[];
  templates: DataTemplate[];
  widgets: WidgetValues;
  waitlistTemplateName: string;
  waitlist: WaitlistSignup[];
  members: Member[];
  pendingInvites: Member[];
};

